me) AS Order_Time ,coalesce(mo.quantity,b.QUANTITY/count(1) over (partition by mo.shopify_ordeR_name, mo.sku)) quantity ,coalesce(mo.order_amount - mo.tax_amount,b.GROSS_SALES_BEFORE_TAX/count(1) over (partition by mo.shopify_ordeR_name, mo.sku)) AS GROSS_SALES_BEFORE_TAX ,coalesce(mo.discount_amount,b.DISCOUNT_BEFORE_TAX/count(1) over (partition by mo.shopify_ordeR_name, mo.sku)) AS DISCOUNT ,coalesce(mo.tax_amount,b.TAX/count(1) over (partition by mo.shopify_ordeR_name, mo.sku)) tax ,b.SHIPPING_PRICE/count(1) over (partition by mo.shopify_ordeR_name, mo.sku) shipping_price ,coalesce(mo.order_amount,b.TOTAL_SALES/count(1) over (partition by mo.shopify_ordeR_name, mo.sku)) AS SELLING_PRICE ,coalesce(mo.order_amount,b.TOTAL_SALES/count(1) over (partition by mo.shopify_ordeR_name, mo.sku)) AS Base_currency_sales ,UPPER(mo.order_Status) as OMS_order_status ,UPPER(coalesce(mo.shipment_status,b.shipping_status)) AS SHIPPING_STATUS ,upper(coalesce(mo.shipment_status,shipmap.final_shipping_status,b.shipping_status)) FINAL_SHIPPING_STATUS ,cast(b.LINE_ITEM_ID as string) as SALEORDERITEMCODE ,b.LINE_ITEM_ID as SALES_ORDER_ITEM_ID ,coalesce(mo.waybill_number,b.awb) AWB ,UPPER(REPLACE(IF(ARRAY_LENGTH(b.GATEWAY) > 0, b.GATEWAY[OFFSET(0)],\'NA\'), \'\"\', \'\')) PAYMENT_GATEWAY ,upper(mo.gateway) Payment_Mode ,Upper(coalesce(mo.logistics_partner,b.courier)) AS COURIER ,cast(timestamp(b.Shipping_created_at) as date) AS DISPATCH_DATE ,coalesce(cast(timestamp(mo.delivered_at) as date),case when mo.shipment_status like \'%delivered%\' then cast(timestamp(mo.updated_at) as date) end) AS DELIVERED_DATE ,case when lower(coalesce(mo.shipment_status,shipmap.final_shipping_status,b.shipping_status)) = \'delivered\' then 1 else 0 end AS DELIVERED_STATUS ,case when mo.IS_RETURN= TRUE and lower(mo.order_status) not in (\'cancel\') then 1 end AS RETURN_FLAG ,case when (case when mo.IS_RETURN= TRUE and lower(mo.order_status) not in (\'cancel\') then 1 end) = 1 and lower(mo.order_status) not in