rdeR_name, mo.sku) base_currency_shipping_price ,coalesce(mo.order_amount,b.TOTAL_SALES/count(1) over (partition by mo.shopify_ordeR_name, mo.sku)) AS base_currency_SELLING_PRICE from symphony-wh.maplemonk.symphony_wh_SHOPIFY_FACT_ITEMS b left join maplemonk.symphony_wh_middleware_orders_fact_items mo on mo.shopify_ordeR_name = b.ordeR_name and mo.sku = b.sku left join ( select * from ( select upper(Shipping_status) shipping_status ,upper(mapped_status) final_shipping_status ,row_number() over (partition by lower(shipping_Status) order by 1) rw from symphony-wh.maplemonk.shipment_status_mapping ) where rw = 1 ) ShipMap on lower(coalesce(mo.shipment_Status,b.shipping_status,mo.order_status,b.ORDER_STATUS)) = lower(ShipMap.shipping_status) UNION ALL select b.customer_id ,UPPER(\'WEBSITE AU CORP\') AS SHOP_NAME ,UPPER(\'WEBSITE AU CORP\') AS marketplace ,Upper(b.FINAL_UTM_CHANNEL) AS CHANNEL ,Upper(coalesce(b.source_name,b.FINAL_UTM_SOURCE)) AS SOURCE ,b.ORDER_ID ,order_name reference_code ,b.PHONE ,b.NAME ,b.EMAIL ,coalesce(cast(b.shipping_status_update_date as timestamp),cast(c.shipping_last_update_date as timestamp), cast(d.shipping_last_update_date as timestamp)) AS SHIPPING_LAST_UPDATE_DATE ,b.SKU ,b.PRODUCT_ID ,Upper(b.PRODUCT_NAME) PRODUCT_NAME ,b.CURRENCY ,Upper(b.CITY) As CITY ,Upper(b.STATE) AS State ,Upper(b.ORDER_STATUS) ORDER_STATUS ,cast(TIMESTAMP(b.ORDER_TIMESTAMP) as date) AS Order_Date ,cast(TIMESTAMP(b.ORDER_TIMESTAMP) as datetime) AS Order_Time ,b.QUANTITY ,b.GROSS_SALES_BEFORE_TAX AS GROSS_SALES_BEFORE_TAX ,b.DISCOUNT_BEFORE_TAX AS DISCOUNT ,b.TAX ,b.SHIPPING_PRICE ,b.TOTAL_SALES AS SELLING_PRICE ,b.PRE_TOTAL_SALES AS Base_currency_sales ,UPPER(coalesce(c.order_status,d.order_status)) as OMS_order_status ,UPPER(coalesce(b.shipping_status, c.shipping_status,d.shipping_status)) AS SHIPPING_STATUS ,upper(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) FINAL_SHIPPING_STATUS ,cast(b.LINE_ITEM_ID as string) 